-- issue #78「サインアップ機能の実装」の本番反映(issue #72の本番DB更新の仕組みによるマイグレーション)。
-- 本ファイルは、SIGN_UPテーブルの新設、及び画面定義・エラーメッセージ等のマスタデータ追加を行う。
-- SIGN_UPの(SESSION_ID, MAIL_ADDRESS)複合一意制約はテーブル定義内のUNIQUE句で表現する。

-- SIGN_UPテーブルを新設する。
CREATE TABLE IF NOT EXISTS SIGN_UP (
    SIGN_UP_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    APROLE_ID INT,
    SESSION_ID VARCHAR(256),
    MAIL_ADDRESS VARCHAR(256),
    ACCOUNT_NAME VARCHAR(256),
    PASSWORD_HASH VARCHAR(256),
    PASSCODE_HASH VARCHAR(256),
    FAIL_CNT INT,
    IS_LOCKED INT,
    EXPIRES_AT TIMESTAMP,
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP,
    UNIQUE (SESSION_ID, MAIL_ADDRESS)
);

-- TBL_DEF: SIGN_UPテーブルの定義を追加する。

-- GNR_KEY_VAL: サインアップ関連のエラーメッセージを追加する。

-- URI_PATTERN: サインアップ画面のURIパターンを追加する。

-- HTML_PARTS: サインアップ画面の画面部品を追加する。

-- SCR: サインアップ関連のスクリプトを追加する。

-- SCR_ELM: サインアップ関連のスクリプト要素(実行サービス)を追加する。

-- HTML_PAGE: サインアップ画面のページ定義を追加する。

-- PARTS_IN_PAGE: サインアップ画面へ組み込む画面部品を追加する。

-- PARTS_ITEM: サインアップ画面の画面表示項目を追加する。

-- HTML_PARTS_IN_APROLE: 全ロールへサインアップ画面部品のedit権限を付与する。
